import { useEffect, useState, useMemo, useRef } from 'react'

import { useClient } from 'cozy-client'
import { useDataProxy } from 'cozy-dataproxy-lib'

import logger from '@/lib/logger'
import { buildRecentQuery } from '@/queries'

const useDataProxyRecents = () => {
  const [data, setData] = useState([])
  const [fetchStatus, setFetchStatus] = useState('loading')
  const [error, setError] = useState(null)
  const [useFallback, setUseFallback] = useState(false)
  const [fallbackData, setFallbackData] = useState(null)
  const [fallbackStatus, setFallbackStatus] = useState('loading')
  const [fallbackError, setFallbackError] = useState(null)
  const dataProxy = useDataProxy()
  const client = useClient()
  const fallbackQueryExecutedRef = useRef(false)

  const recentQuery = useMemo(() => buildRecentQuery(), [])

  // Use useMemo to create stable references for comparison
  const fallbackDataLength = useMemo(
    () => (Array.isArray(fallbackData) ? fallbackData.length : 0),
    [fallbackData]
  )
  const fallbackDataId = useMemo(() => {
    if (!Array.isArray(fallbackData) || fallbackData.length === 0) return null
    // Use first item's _id as a stable identifier for the dataset
    return fallbackData[0]?._id || null
  }, [fallbackData])

  // Track previous values to avoid unnecessary updates
  const prevDataRef = useRef(null)
  const prevStatusRef = useRef(null)
  const prevErrorRef = useRef(null)

  useEffect(() => {
    const fetchRecents = async () => {
      setFetchStatus('loading')
      setError(null)
      try {
        const data = await dataProxy.recents()
        setData(data || [])
        setFetchStatus('loaded')
        setUseFallback(false)
      } catch (err) {
        logger.warn('Error fetching recents from dataproxy', err)
        setError(err)
        setUseFallback(true)
      }
    }

    if (dataProxy.dataProxyServicesAvailable) {
      fetchRecents()
    } else {
      setUseFallback(true)
    }
  }, [dataProxy])

  // Use fallback query result if dataProxy failed or is not available
  useEffect(() => {
    if (!useFallback) {
      return
    }

    // Check if status changed
    const statusChanged = fallbackStatus !== prevStatusRef.current

    if (fallbackStatus === 'loaded' && fallbackData) {
      // Check if data actually changed by comparing length and first item ID
      const dataChanged =
        !prevDataRef.current ||
        prevDataRef.current.length !== fallbackDataLength ||
        prevDataRef.current.id !== fallbackDataId

      if (statusChanged || dataChanged) {
        prevDataRef.current = { length: fallbackDataLength, id: fallbackDataId }
        prevStatusRef.current = fallbackStatus
        setData(fallbackData)
        setFetchStatus('loaded')
        setError(null)
      }
      return
    }

    if (fallbackStatus === 'error') {
      // Check if error actually changed
      const errorChanged =
        fallbackError !== prevErrorRef.current || statusChanged

      if (errorChanged) {
        prevErrorRef.current = fallbackError
        prevStatusRef.current = fallbackStatus
        setFetchStatus('error')
        setError(fallbackError)
      }
      return
    }

    if (fallbackStatus === 'loading' && statusChanged) {
      prevStatusRef.current = fallbackStatus
      setFetchStatus('loading')
    }
  }, [
    useFallback,
    fallbackStatus,
    fallbackData,
    fallbackError,
    fallbackDataLength,
    fallbackDataId
  ])

  return { data, fetchStatus, error }
}

export default useDataProxyRecents
